#: The launcher constants the parsers read when they are built, rebound to markers to show each is read then.
#: Ordered and deliberately unsorted (a set's order would depend on the hash seed), so sorting, listing and picking are all visible;
#: the layout default is neither the first nor the last choice.
MARKERS = {"AGENT_CLI_POLICIES": ("syrd411-policy-z", "syrd411-policy-a"), "LAYOUT_MODE_AUTO": "syrd411-m-auto",
           "LAYOUT_MODE_CHOICES": ("syrd411-z-other", "syrd411-m-auto", "syrd411-a-other"), "LAYOUT_MODE_SEPARATE": "syrd411-separate",
           "LAYOUT_MODE_VIEWER": "syrd411-viewer", "SUPPORTED_CONFIG_CLI_NAMES": ("syrd411-z-cli", "syrd411-a-cli")}


def shown(value: object) -> object:
    if isinstance(value, Path):
        return f"PATH {value}"
    if isinstance(value, (list, tuple)):
        return [shown(v) for v in value]
    if isinstance(value, (set, frozenset)):
        return sorted(shown(v) for v in value)
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    return repr(value)


def structure(parser: argparse.ArgumentParser) -> dict:
    actions = [{"class": type(a).__name__, "option_strings": list(a.option_strings), "dest": a.dest, "nargs": shown(a.nargs),
                "const": shown(a.const), "default": shown(a.default), "type": getattr(a.type, "__name__", shown(a.type)),
                "choices": shown(list(a.choices)) if a.choices is not None else None, "required": a.required,
                "metavar": shown(a.metavar), "help": a.help,
                "subcommands": {k: structure(v) for k, v in a.choices.items()} if isinstance(a, argparse._SubParsersAction) else None}
               for a in parser._actions]
    groups = [{"dests": [a.dest for a in g._group_actions], "required": g.required} for g in parser._mutually_exclusive_groups]
    return {"prog": parser.prog, "description": parser.description, "epilog": parser.epilog, "actions": actions, "exclusive": groups}


def parse(parser: argparse.ArgumentParser, argv: list) -> dict:
    err = io.StringIO()
    try:
        with contextlib.redirect_stderr(err):
            return {"argv": argv, "parsed": {k: shown(v) for k, v in sorted(vars(parser.parse_args(argv)).items())}}
    except SystemExit as exc:
        return {"argv": argv, "exit": exc.code, "stderr": err.getvalue()}


def sample(action: argparse.Action) -> list:
    if action.choices is not None:
        return [str(list(action.choices)[-1])]
    if action.type is int:
        return ["7"]
    if action.type is Path:
        return ["/nonexistent/syrd411/value"]
    return ["v411"]


def fill(action: argparse.Action) -> str:
    if action.choices is not None:
        return str(list(action.choices)[0])
    return "demo" if action.type in (None, str) else sample(action)[0]


def generated_parses(parser: argparse.ArgumentParser, prefix: list | None = None) -> dict:
    """One parse of the required arguments alone, one per optional on top of them, and the same inside every sub-command."""
    base = list(prefix or [])
    subs = None
    for a in parser._actions:
        if isinstance(a, argparse._SubParsersAction):
            subs = a
        elif not a.option_strings and a.nargs in (None, "+", 1):
            base.append(fill(a))
        elif a.option_strings and a.required:
            base += [a.option_strings[-1], *sample(a)]
    out = {"required only": parse_all(parser, prefix, base)}
    for a in parser._actions:
        if not a.option_strings or isinstance(a, argparse._HelpAction) or a.required:
            continue
        flag = a.option_strings[-1]
        if a.nargs == 0:
            argv = [*base, flag]
        elif isinstance(a.nargs, int):
            argv = [*base, flag, *(sample(a) * a.nargs)]
        else:
            argv = [*base, flag, *sample(a)]
        out[flag] = parse_all(parser, prefix, argv)
    if subs is not None:
        for name, sub in subs.choices.items():
            for label, case in generated_parses(sub, [*base, name]).items():
                out[f"{name} {label}"] = case
    return out


def parse_all(parser: argparse.ArgumentParser, prefix: list | None, argv: list) -> dict:
    """Sub-command cases are parsed by the top-level parser, as the command line is."""
    return parse(ROOT_PARSER[-1], argv)


ROOT_PARSER: list = []


def parser_case(holder: object, name: str) -> dict:
    saved = os.environ.get("COLUMNS")
    os.environ["COLUMNS"] = "100"
    try:
        parser = getattr(holder, name)()
        if not isinstance(parser, argparse.ArgumentParser):  # an answer to compare, not a crash
            return {"returned": type(parser).__name__}
        ROOT_PARSER.append(parser)
        try:
            return {"structure": structure(parser), "usage": parser.format_usage(), "help": parser.format_help(),
                    "no arguments": parse(parser, []), "parses": generated_parses(parser)}
        finally:
            ROOT_PARSER.pop()
    finally:
        if saved is None:
            os.environ.pop("COLUMNS", None)
        else:
            os.environ["COLUMNS"] = saved


def walk_choices(s: dict, where: str = ""):
    for a in s["actions"]:
        if a["choices"] is not None:
            yield (f"{where}{a['dest']}", a["choices"], a["default"])
        for sub, nested in (a["subcommands"] or {}).items():
            yield from walk_choices(nested, f"{where}{sub}.")


def marker_case(t: object, holder: object, catalogue_home: object) -> dict:
    """The four readers built with the launcher's constants, and the privileged catalogue, rebound to markers."""
    saved = {n: getattr(t, n) for n in MARKERS}
    saved_catalogue = catalogue_home.CATALOGUE
    for n, v in MARKERS.items():
        setattr(t, n, v)
    catalogue_home.CATALOGUE = (SimpleNamespace(name="syrd411-marker-action"),)
    try:
        out = {}
        for name in ("_build_switchyard_new_parser", "_build_switchyard_add_role_parser", "_build_switchyard_set_role_runtime_parser",
                     "_build_switchyard_present_parser", "_build_switchyard_privileged_action_parser"):
            s = structure(getattr(holder, name)())
            out[name] = {"description": s["description"], "choices": list(walk_choices(s))}
        return out
    finally:
        for n, v in saved.items():
            setattr(t, n, v)
        catalogue_home.CATALOGUE = saved_catalogue
# ----------------------------------------------------------------------------------------------------------------------

MOVED = tuple(PARSERS)


def check(condition: bool, detail: str) -> None:
    global CHECKS
    assert condition, detail
    CHECKS += 1


def python(probe: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run([sys.executable, "-c", probe], cwd=ROOT, capture_output=True, text=True,
                          env={"PATH": "/usr/bin:/bin"}, check=False)


class patched:
    def __init__(self, target: object, **values: object) -> None:
        self.target, self.values = target, values

    def __enter__(self) -> None:
        self.saved = {name: getattr(self.target, name) for name in self.values}
        for name, value in self.values.items():
            setattr(self.target, name, value)

    def __exit__(self, *exc: object) -> None:
        for name, value in self.saved.items():
            setattr(self.target, name, value)


def refuse(what: str):
    def refused(*args: object, **kwargs: object) -> object:
        raise AssertionError(f"{what} was called: {args} {kwargs}")
    return refused


class contained:
    """Spawns, signals, account lookups and connections refused."""

    def __enter__(self) -> None:
        self.parts = [patched(subprocess, run=refuse("subprocess.run"), Popen=refuse("subprocess.Popen")),
                      patched(os, kill=refuse("os.kill")), patched(pwd, getpwnam=refuse("pwd.getpwnam"), getpwuid=refuse("pwd.getpwuid")),
                      patched(socket.socket, connect=refuse("socket.connect"), connect_ex=refuse("socket.connect_ex"))]
        for part in self.parts:
            part.__enter__()

    def __exit__(self, *exc: object) -> None:
        for part in reversed(self.parts):
            part.__exit__(*exc)


def test_the_guard_itself_refuses_a_spawn_a_signal_a_lookup_and_a_connection() -> None:
    for attempt in (lambda: subprocess.run(["true"]), lambda: subprocess.Popen(["true"]), lambda: os.kill(os.getpid(), 0),
                    lambda: pwd.getpwuid(0), lambda: socket.socket().connect(("127.0.0.1", 9))):
        with contained():
            try:
                attempt()
            except AssertionError as exc:
                refused = " was called: " in str(exc)
            else:
                refused = False
        check(refused, "the guard refuses a spawn, a signal, an account lookup and a connection")


