def test_the_module_loads_nothing_of_switchyards_at_import() -> None:
    result = python("import sys, scripts.switchyard_parsers as m; "
                    "print(sorted(n for n in sys.modules if n.startswith('scripts.') and n != m.__name__))")
    check(result.returncode == 0 and result.stdout.strip() == "[]",
          f"it imports on its own and loads nothing else of Switchyard's: {result.stdout}{result.stderr[-400:]}")


def test_either_import_order_gives_one_set_of_objects() -> None:
    for order in (("scripts.switchyard_parsers", "scripts.team_launcher"), ("scripts.team_launcher", "scripts.switchyard_parsers")):
        result = python("import importlib, inspect; "
                        f"[importlib.import_module(n) for n in {order!r}]; "
                        "import scripts.team_launcher as t, scripts.switchyard_parsers as m; "
                        f"print(all(getattr(t, n) is getattr(m, n) for n in {MOVED!r}), "
                        f"all(list(inspect.signature(getattr(m, n)).parameters) == [] for n in {MOVED!r}), "
                        "not hasattr(m, 'launcher') and not hasattr(m, 'privileged_actions') and not hasattr(m, 'LAYOUT_MODE_AUTO'))")
        check(result.stdout.strip() == "True True True", f"{' then '.join(order)}: {result.stdout}{result.stderr[-600:]}")
    check(m.argparse is argparse and m.Path is Path, "the standard-library names are the module's own")


def test_the_seams_read_through_the_launcher_and_nothing_bound() -> None:
    tree = ast.parse((ROOT / "scripts" / "switchyard_parsers.py").read_text(encoding="utf-8"))
    for name in MOVED:
        node = next(n for n in tree.body if getattr(n, "name", None) == name)
        through: dict[str, int] = {}
        for x in ast.walk(node):
            if isinstance(x, ast.Attribute) and isinstance(x.value, ast.Name) and x.value.id == "launcher":
                through[x.attr] = through.get(x.attr, 0) + 1
        expected = SEAMS.get(name, {})
        check(through == expected, f"{name}: each launcher name read through it exactly as often as before: {through}")
        imports = [ast.unparse(x) for x in ast.walk(node) if isinstance(x, (ast.Import, ast.ImportFrom))]
        own = ["from scripts.ticket_board import privileged_actions"] if name == "_build_switchyard_privileged_action_parser" else []
        check(imports == (["from scripts import team_launcher as launcher"] if expected else []) + own
              and (not imports or ast.unparse(node.body[0]) == imports[0]),
              f"{name}: the launcher first thing when it reads one, and only the catalogue otherwise: {imports}")
        bare = sorted({x.id for x in ast.walk(node) if isinstance(x, ast.Name) and isinstance(x.ctx, ast.Load) and x.id in expected})
        check(bare == [], f"{name}: none of them read past it: {bare}")
        check(not node.args.args and not node.args.kwonlyargs and ast.unparse(node.returns) == "argparse.ArgumentParser", f"{name}: no argument, the same return annotation")
    top = [ast.unparse(n) for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom))]
    check(top == ["from __future__ import annotations", "import argparse", "from pathlib import Path"] and not [n for n in tree.body if isinstance(n, ast.If)],
          f"only the standard library at the top: {top}")
    check([n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Assign))] == list(MOVED), "the twenty-one in the launcher's order, and nothing else")


def test_the_launcher_reexports_the_twenty_one_and_builds_them_there() -> None:
    tree = ast.parse((ROOT / "scripts" / "team_launcher.py").read_text(encoding="utf-8"))
    imports = [n for n in tree.body if isinstance(n, ast.ImportFrom) and n.module == "scripts.switchyard_parsers"]
    check(len(imports) == 1 and sorted(a.name for a in imports[0].names) == sorted(MOVED) and all(a.asname is None for a in imports[0].names),
          "one explicit import of exactly the twenty-one, unaliased")
    check(imports[0].lineno < min(n.lineno for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef))),
          "at the top, above every definition that could build them")
    defined = {getattr(n, "name", None) for n in tree.body} | {x.id for n in tree.body if isinstance(n, ast.Assign) for x in n.targets if isinstance(x, ast.Name)}
    # A neighbour stays reachable on the launcher: defined there, or -- once a later slice moves it on -- re-exported there, unaliased.
    exported = {a.name for n in tree.body if isinstance(n, ast.ImportFrom) and (n.module or "").startswith("scripts.")
                for a in n.names if a.asname is None}
    check(not defined & set(MOVED) and {"_build_parser", "rollout_log_command", "_owner_account_exists", "_owner_catalog_args",
                                        "switchyard_attach_command", "switchyard_main", "switchyard_recover_display_command"} <= defined | exported,
          "the launcher defines none of them, and keeps its neighbours and both callers, its own or re-exported")
    calls: dict = {}
    for fn in tree.body:
        if isinstance(fn, ast.FunctionDef):
            for x in ast.walk(fn):
                if isinstance(x, ast.Call) and ast.unparse(x.func).split(".")[-1] in MOVED:
                    calls.setdefault(fn.name, {}).setdefault(ast.unparse(x.func), 0)
                    calls[fn.name][ast.unparse(x.func)] += 1
    # SYRD-412 moved switchyard_recover_display_command on: follow the launcher's exact unaliased re-export of a
    # caller it no longer defines, and count its builds there, which must read the launcher's names.
    for caller in sorted(set(DISPATCH) - defined):
        source = [n.module for n in tree.body if isinstance(n, ast.ImportFrom) and (n.module or "").startswith("scripts.")
                  and any(a.name == caller and a.asname is None for a in n.names)]
        check(len(source) == 1, f"the launcher re-exports {caller}, unaliased: {source}")
        module = ast.parse((ROOT / f"{source[0].replace('.', '/')}.py").read_text(encoding="utf-8"))
        fn = next(n for n in module.body if isinstance(n, ast.FunctionDef) and n.name == caller)
        for x in ast.walk(fn):
            if isinstance(x, ast.Call) and ast.unparse(x.func).startswith("launcher.") and ast.unparse(x.func)[len("launcher."):] in MOVED:
                calls.setdefault(caller, {}).setdefault(ast.unparse(x.func)[len("launcher."):], 0)
                calls[caller][ast.unparse(x.func)[len("launcher."):]] += 1
    check(calls == DISPATCH, f"both callers build them by the launcher's own globals, as often as before: {calls}")


