def test_every_parser_is_the_baselines() -> None:
    check(sorted(PARSERS) == sorted(k for k in GOLDEN if k != "markers"), "every measured parser is asserted, and nothing else")
    for name in PARSERS:
        with contained():
            got = json.loads(json.dumps(parser_case(m, name)))  # as the golden file holds it
        for part in ("structure", "usage", "help", "no arguments", "parses"):
            check(got.get(part) == GOLDEN[name][part], f"{name} {part}: the baseline's: {str(got.get(part, got))[:600]}")


def test_the_launcher_constants_and_the_catalogue_are_read_when_built() -> None:
    with contained():
        got = json.loads(json.dumps(marker_case(t, m, privileged_actions)))  # as the golden file holds it
    check(got == GOLDEN["markers"], f"rebound on the launcher (and the catalogue on its module), each reaches the built parser: {got}")
    check(all("syrd411" in str(v) for v in got.values()), "every reader shows its marker")


STRUCTURE = ("test_the_module_loads_nothing_of_switchyards_at_import", "test_either_import_order_gives_one_set_of_objects",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_the_twenty_one_and_builds_them_there")
LAST: tuple = ()


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"switchyard_parsers_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
